import { createSelector } from '@reduxjs/toolkit';

// Base selectors
const selectUsers = (state) => state.users.items;
const selectActiveFilter = (state) => state.users.activeFilter;

// Memoized selector - only recomputes when users or filter changes
const selectFilteredUsers = createSelector(
  [selectUsers, selectActiveFilter],
  (users, filter) => {
    console.log('Computing filtered users...');
    if (filter === 'all') return users;
    return users.filter(user => user.role === filter);
  }
);

// In a component
function UserList() {
  const filteredUsers = useSelector(selectFilteredUsers);
  return (
    <ul>
      {filteredUsers.map(user => (
        <li key={user.id}>{user.name}</li>
      ))}
    </ul>
  );
}

