const UserProfile = ({ user, isLoading }) => (
  <div>{isLoading ? 'Loading...' : user.name}</div>
);

const mapStateToProps = (state) => ({
  user: state.user.data,
  isLoading: state.user.isLoading,
});

export default connect(mapStateToProps)(UserProfile);

// Modern approach with hooks (clean)
import { useSelector } from 'react-redux';

export function UserProfile() {
  const user = useSelector((state) => state.user.data);
  const isLoading = useSelector((state) => state.user.isLoading);
  return <div>{isLoading ? 'Loading...' : user.name}</div>;
}

import { useSelector } from 'react-redux';
import { selectUser, selectUserPermissions } from './selectors';

function Dashboard() {
  // Each useSelector call is independent
  const user = useSelector(selectUser);
  const permissions = useSelector(selectUserPermissions);
  const theme = useSelector((state) => state.ui.theme);
  const notifications = useSelector((state) => state.notifications.unread);

  return (
    <div className={theme}>
      <h1>Welcome, {user.name}</h1>
      <p>You have {notifications} new notifications</p>
      {permissions.canEdit && <EditButton />}
    </div>
  );
}
